39 | export async function getProject(projectId: string): Promise<Project> {
40 |   const response = await fetch(`${apiBaseUrl}/api/projects/${encodeURIComponent(projectId)}`)
41 |   if (!response.ok) {
42 |     throw await apiError(response)
43 |   }
44 |   return response.json() as Promise<Project>
45 | }
